package org.sleepwell.app;
import org.junit.Test;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.Assert.*;
/** Actual policy/group/cue/clip boundaries with fake scores and effects; no hardware. */
public final class SoundInclusionTest {
 static float[] snore(){float[] s=new float[521];s[38]=.9f;s[100]=.4f;return s;}
 List<String> grouped(SoundSensitivity policy,List<SoundAnalysis.Result> input){List<String> out=new ArrayList<>();SoundAnalysis.Group group=new SoundAnalysis.Group((a,n,c,s)->out.add(a+":"+n+":"+c+":"+s),policy);for(int n=0;n<input.size();n++)group.add(1+n*975L,input.get(n));group.flush();return out;}
 @Test public void defaultAllCategoriesAndClipConsentAreExactLegacy(){for(String c:SoundSensitivity.SELECTABLE)assertTrue(SoundSensitivity.DEFAULT.includes(c));assertTrue(SoundSensitivity.DEFAULT.allIncluded());ClipBudget b=new ClipBudget();assertTrue(b.permitsClips(true));assertFalse(b.permitsClips(false));assertTrue(b.canStart(0));List<SoundAnalysis.Result> input=List.of(new SoundAnalysis.Result("speech",.8),new SoundAnalysis.Result("speech",.9));assertEquals(List.of("1:2:speech:0.8500000000000001"),grouped(SoundSensitivity.DEFAULT,input));}
 @Test public void eachDisabledWinnerIsDroppedAndNeverRelabeledOther(){for(String c:SoundSensitivity.SELECTABLE){SoundSensitivity selected=SoundSensitivity.DEFAULT.include(c,false);assertFalse(selected.includes(c));SoundAnalysis.Result value=new SoundAnalysis.Result(c,.9);assertTrue(grouped(selected,List.of(value,value)).isEmpty());for(String other:SoundSensitivity.SELECTABLE)if(!other.equals(c))assertTrue(selected.includes(other));}}
 @Test public void realClassificationWinnerIsNotChangedToRunnerUp(){float[] scores=snore();SoundAnalysis.Result before=SoundAnalysis.classify(scores);assertEquals("snoring",before.category);SoundSensitivity selected=SoundSensitivity.DEFAULT.include("snoring",false);List<String> out=new ArrayList<>();try(SoundAnalysisStream stream=new SoundAnalysisStream(()->new SoundAnalysisStream.Model(){public float[] infer(float[] pcm){return scores;}public void close(){}},(a,n,c,s)->out.add(c),()->fail(),selected)){stream.accept(new short[31200],31200,5000);}assertTrue(out.isEmpty());assertEquals("snoring",SoundAnalysis.classify(scores).category);assertEquals(.9f,scores[38],0);}
 @Test public void otherSelectionIsIndependentAndCannotTakeDisabledWinner(){SoundSensitivity p=SoundSensitivity.DEFAULT.include("noise",false);assertEquals(1,grouped(p,List.of(new SoundAnalysis.Result("snoring",.9),new SoundAnalysis.Result("snoring",.9))).size());assertTrue(grouped(p,List.of(new SoundAnalysis.Result("noise",.9),new SoundAnalysis.Result("noise",.9))).isEmpty());SoundSensitivity q=SoundSensitivity.DEFAULT.include("snoring",false);assertEquals(1,grouped(q,List.of(new SoundAnalysis.Result("noise",.9),new SoundAnalysis.Result("noise",.9))).size());}
 @Test public void filteredGapCannotBridgeSelectedTemporalEvent(){SoundSensitivity p=SoundSensitivity.DEFAULT.include("speech",false);assertTrue(grouped(p,List.of(new SoundAnalysis.Result("snoring",.9),new SoundAnalysis.Result("speech",.9),new SoundAnalysis.Result("snoring",.9))).isEmpty());}
 @Test public void snapshotOwnsSelectionAndDurationAcrossLaterCopies(){SoundSensitivity old=SoundSensitivity.DEFAULT.include("speech",false);ClipBudget run=new ClipBudget(old);SoundSensitivity next=old.include("speech",true).include("cough",false).with("snoring",1);assertFalse(run.sensitivity.includes("speech"));assertTrue(run.sensitivity.includes("cough"));assertEquals(2,run.sensitivity.windows("snoring"));assertTrue(next.includes("speech"));assertFalse(next.includes("cough"));}
 @Test public void anyCustomSelectionBlocksEveryNewClipWithoutChangingConsent(){for(String c:SoundSensitivity.SELECTABLE){ClipBudget b=new ClipBudget(SoundSensitivity.DEFAULT.include(c,false));assertFalse(b.permitsClips(true));assertFalse(b.permitsClips(false));assertFalse(b.canStart(0));assertFalse(b.canStart(100000));assertTrue(b.saveEvent());}assertTrue(new ClipBudget().permitsClips(true));}
 @Test public void droppedSnoreCannotAllocateCueOrSpendItsBudget(){AtomicInteger devices=new AtomicInteger(),plays=new AtomicInteger();SnoreCuePolicy.Budget budget=new SnoreCuePolicy.Budget();SnoreCuePolicy.Settings settings=new SnoreCuePolicy.Settings(true,SnoreCuePolicy.Mode.SOUND,1,1,1);try(SnoreCuePolicy cue=new SnoreCuePolicy(budget,()->{devices.incrementAndGet();return new SnoreCuePolicy.Device(){public void play(SnoreCuePolicy.Settings s){plays.incrementAndGet();}public void close(){}};},()->fail())){SoundAnalysis.Group off=new SoundAnalysis.Group((a,n,c,s)->cue.event(c,s,1000,settings),SoundSensitivity.DEFAULT.include("snoring",false));off.add(1,SoundAnalysis.classify(snore()));off.add(976,SoundAnalysis.classify(snore()));off.flush();assertEquals(0,devices.get());assertEquals(0,plays.get());assertTrue(cue.event("snoring",.9,1000,settings));assertEquals(1,plays.get());}}
 @Test public void emptyUnknownOrMutableInputCannotBecomeAnAnalysisPolicy(){Map<String,Integer> values=new HashMap<>();for(String key:SoundSensitivity.CATEGORIES)values.put(key,2);assertThrows(IllegalArgumentException.class,()->new SoundSensitivity(values,Set.of()));assertThrows(IllegalArgumentException.class,()->new SoundSensitivity(values,Set.of("unknown")));Set<String> chosen=new HashSet<>(Set.of("speech"));SoundSensitivity p=new SoundSensitivity(values,chosen);chosen.clear();values.put("speech",1);assertTrue(p.includes("speech"));assertEquals(2,p.windows("speech"));assertThrows(IllegalArgumentException.class,()->p.include("speech",false));}
 @Test public void rejectedClassDoesNotSpendPersistentEventBudget(){ClipBudget b=new ClipBudget(SoundSensitivity.DEFAULT.include("snoring",false));AtomicInteger saved=new AtomicInteger();SoundAnalysis.Group group=new SoundAnalysis.Group((a,n,c,score)->{assertTrue(b.saveEvent());saved.incrementAndGet();},b.sensitivity);for(int n=0;n<7200;n++)group.add(1+975L*n,new SoundAnalysis.Result("snoring",.9));group.add(8000000,new SoundAnalysis.Result("speech",.9));group.add(8000975,new SoundAnalysis.Result("speech",.9));group.flush();assertEquals(1,saved.get());}
 @Test public void sharedSonarUsesTheSameSelectedWinnerDropWithoutAnotherMicrophone(){SonarSoundPipelineTest.Fake fake=new SonarSoundPipelineTest.Fake();fake.speech=true;List<String> events=new ArrayList<>();try(SonarSoundPipeline pipeline=new SonarSoundPipeline(fake,(a,n,c,score)->events.add(c),SonarSoundPipelineTest.WALL,SonarSoundPipelineTest.ORIGIN,SoundSensitivity.DEFAULT.include("speech",false))){new SonarSoundPipelineTest().blocks(pipeline,0,55);}assertTrue(events.isEmpty());assertTrue(fake.calls>=2);assertEquals(1,fake.closed);}

 @Test public void unreadableRuntimePolicyCannotAllocateModelOrClipsAndDoesNotPretendCompletion(){SoundSensitivity blocked=SoundSensitivity.blocked();ClipBudget budget=new ClipBudget(blocked);assertFalse(budget.analysisAllowed());assertFalse(budget.permitsClips(true));assertFalse(budget.canStart(0));AtomicInteger failures=new AtomicInteger();try(SoundAnalysisStream stream=new SoundAnalysisStream(()->{fail("No model allocation for unreadable settings");return null;},(a,count,c,score)->fail("No event"),failures::incrementAndGet,blocked)){stream.accept(new short[31200],31200,5000);}assertEquals(1,failures.get());assertTrue(grouped(blocked,List.of(new SoundAnalysis.Result("snoring",.9),new SoundAnalysis.Result("snoring",.9))).isEmpty());SonarSoundPipelineTest.Fake fake=new SonarSoundPipelineTest.Fake();try(SonarSoundPipeline sonar=new SonarSoundPipeline(fake,(a,count,c,score)->fail(),SonarSoundPipelineTest.WALL,SonarSoundPipelineTest.ORIGIN,blocked)){new SonarSoundPipelineTest().blocks(sonar,0,55);assertEquals("capture",sonar.issue());assertEquals(0,sonar.frames());}assertEquals(0,fake.loaded);}
 @Test public void blockedSharedNightPublishesAnErrorWithoutAnalysisWorkerOrNewPortableState(){List<SoundAnalysisStatus> statuses=new ArrayList<>();SonarNightSound night=new SonarNightSound(true,()->{fail("No analysis worker/model");return null;},new SonarNightSound.Port(){public void event(long at,long duration,String c,double score){fail();}public void status(SoundAnalysisStatus value){statuses.add(value);}},3600,SoundSensitivity.blocked());assertNull(night.begin(1000,1000,0,Runnable::run));assertEquals(1,statuses.size());assertEquals("error",statuses.get(0).state);assertEquals("capture",statuses.get(0).issue);assertEquals(0,statuses.get(0).frames);assertEquals("error",night.ended(false).state);}

}
